def get_spike_times_for_unit(f, unit_idx, spike_times_data, spike_times_index):
    """Get spike times for a single unit from pre-loaded arrays."""
    if unit_idx == 0:
        start = 0
    else:
        start = int(spike_times_index[unit_idx - 1])
    end = int(spike_times_index[unit_idx])
    return spike_times_data[start:end]


def bin_spike_times(spike_times_trial, bin_edges):
    """Bin spike times into firing rates using histogram."""
    counts, _ = np.histogram(spike_times_trial, bins=bin_edges)
    bin_width = bin_edges[1] - bin_edges[0]
    return counts / bin_width  # Convert to firing rate (Hz)

